function supplierColourRecord({
  supplierId,
  supplierName,
  colourId,
  name,
  code = "",
  finish = "",
  systems = [],
  hex = "#d8dee8",
  availability = "Available",
  regionAvailability = ["National"],
  sourceUrl = "",
  lastVerified = "",
  demo = false,
}) {
  return {
    supplierId,
    supplierName,
    colourId,
    id: colourId,
    name,
    officialName: name,
    code,
    supplierCode: code,
    finish,
    type: /quote|custom|designer|anod/i.test(availability) ? "quote_required" : "standard",
    systems,
    compatibleSystems: systems,
    hex,
    swatchValue: hex,
    availability,
    availabilityStatus: demo ? `${availability} - demo code pending supplier confirmation` : availability,
    regionAvailability,
    sourceUrl,
    officialSourceUrl: sourceUrl,
    lastVerified,
    demo,
  };
}

